// Confere o formulário do dono e cria os códigos do programa (ex.: "cafe-da-praca-3f9a"), a chave do painel e o segredo que assina os QR do balcão.
let b = $('🔔 Pedido de criação (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '').slice(0, 34);
const opcao = (v, lista, padrao) => lista.includes(Number(v)) ? Number(v) : padrao;
const crypto = require('crypto');

const dados = {
  nome: limpa(b.nome, 60),
  tipo: limpa(b.tipo, 40),
  meta: opcao(b.meta, [5, 6, 8, 10, 12, 15, 20], 10),
  premio: limpa(b.premio, 80),
  regra: limpa(b.regra, 160),
  intervalo_h: opcao(b.intervalo_h, [0, 1, 4, 12, 24], 4),
  aniversario: limpa(b.aniversario, 80),
  dias_saudade: opcao(b.dias_saudade, [0, 15, 30, 45, 60], 30),
  whatsapp: String(b.whatsapp || '').replace(/\D/g, '').slice(0, 15),
  instagram: limpa(b.instagram, 40).replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, ''),
  endereco: limpa(b.endereco, 200),
  cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : '',
};
const erros = [];
if (dados.nome.length < 2) erros.push('Digite o nome do negócio.');
if (dados.premio.length < 3) erros.push('Diga qual é o prêmio (ex.: 1 café expresso).');
if (dados.whatsapp && dados.whatsapp.length < 10) erros.push('O WhatsApp precisa ter DDD.');
if (dados.whatsapp.length >= 10 && dados.whatsapp.length <= 11) dados.whatsapp = '55' + dados.whatsapp;

const id = (slug(dados.nome) || 'fidelidade') + '-' + crypto.randomBytes(2).toString('hex');
const chave = crypto.randomBytes(6).toString('hex');
const base = String($('🔔 Pedido de criação (POST)').first().json.webhookUrl || '').split('/webhook/')[0] + '/webhook';
return [{ json: { valido: erros.length === 0, erros, id, chave, segredo: crypto.randomBytes(16).toString('hex'), dados,
  chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13),
  cartao_url: `${base}/fidelidade/${id}/cartao`, balcao_url: `${base}/fidelidade-balcao?id=${id}&chave=${chave}`,
  painel_url: `${base}/fidelidade-painel?id=${id}&chave=${chave}` } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Lê os textos da redatora e prepara o pedido da revisora (ela confere tudo contra os dados do dono).
const d = $('🧩 Confere o pedido').first().json.dados;
let r = null;
try { r = parseJSON($('🤖 Redatora do programa').first().json.output); } catch (e) {}
const dono = { negocio: d.nome, ramo: d.tipo, carimbos_para_o_premio: d.meta, premio: d.premio, quando_ganha_carimbo: d.regra || '(não informado: a cada visita)',
  presente_de_aniversario: d.aniversario || '(nenhum)', avisar_quem_sumiu_depois_de_dias: d.dias_saudade || '(desligado)' };
return [{ json: { escreveu: !!r, texto_revisora: 'DADOS DO DONO (a única fonte de verdade):\n' + JSON.stringify(dono, null, 1)
  + '\n\nTEXTOS DA REDATORA:\n' + (r ? JSON.stringify(r, null, 1) : '(a redatora não respondeu: escreva todos os campos você mesma, seguindo as regras)') } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Junta o que o dono digitou com os textos revisados. Campo vazio da revisora fica o da redatora; se as duas falharem, sai o texto padrão.
const base = $('🧩 Confere o pedido').first().json;
const d = base.dados;
const crypto = require('crypto');
let red = null, rev = null;
try { red = parseJSON($('🤖 Redatora do programa').first().json.output); } catch (e) {}
try { rev = parseJSON($('🤖 Revisora do programa').first().json.output); } catch (e) {}
red = red || {}; rev = rev || {};
const txt = (v, max) => String(v ?? '').replace(/[<>]/g, '').trim().slice(0, max);
const campo = k => (rev[k] !== undefined && rev[k] !== '' && rev[k] !== null) ? rev[k] : red[k];
const aviso = (v, padrao, max = 120) => (v && v.titulo && v.texto) ? { titulo: txt(v.titulo, 44), texto: txt(v.texto, max) } : padrao;
const corOk = c => /^#[0-9a-fA-F]{6}$/.test(c || '');

const comoPadrao = [d.regra ? 'Ganhe 1 carimbo ' + d.regra.replace(/^ganhe\s+/i, '') : 'Ganhe 1 carimbo a cada visita', `Junte ${d.meta} carimbos`, 'Mostre o cartão e retire seu prêmio'];
let como = campo('como_funciona');
como = Array.isArray(como) ? como.map(x => txt(x, 70)).filter(Boolean).slice(0, 4) : [];
let quase = aviso(campo('aviso_quase'), null);
if (!quase || !quase.texto.includes('{faltam}')) quase = { titulo: '⭐ Falta pouco!', texto: `Faltam só {faltam} carimbos para ${d.premio}. Passe aqui!` };

const { privateKey, publicKey } = crypto.generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
const jwk = privateKey.export({ format: 'jwk' }), pub = publicKey.export({ format: 'jwk' });
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
const palavras = d.nome.split(/\s+/).filter(p => p.length > 2 || /^[A-Z0-9]/.test(p));
const iniciais = ((palavras[0] || d.nome)[0] + (palavras[1] ? palavras[1][0] : (palavras[0] || '').slice(1, 2))).toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Z0-9]/g, '') || 'CF';

const programa = {
  id: base.id, chave: base.chave, segredo: base.segredo, criado_em: new Date().toISOString(),
  feito_com_ia: !!red.chamada, revisado: !!(rev.chamada || rev.problemas), problemas_revisao: Array.isArray(rev.problemas) ? rev.problemas.map(p => txt(p, 200)).slice(0, 10) : [],
  nome: d.nome, nome_curto: txt(campo('nome_curto'), 12) || d.nome.slice(0, 12), tipo: d.tipo,
  meta: d.meta, premio: d.premio, regra: d.regra, intervalo_h: d.intervalo_h, aniversario: d.aniversario, dias_saudade: d.dias_saudade,
  chamada: txt(campo('chamada'), 70) || `Junte ${d.meta} carimbos e ganhe ${d.premio}`,
  boas_vindas: txt(campo('boas_vindas'), 180) || `Seu cartão da ${d.nome} está pronto! A cada visita, leia o QR do balcão e ganhe um carimbo.`,
  como_funciona: como.length >= 2 ? como : comoPadrao,
  emoji: txt(campo('emoji'), 4) || '⭐',
  cor: corOk(d.cor) ? d.cor : (corOk(campo('cor')) ? campo('cor') : '#9a3412'),
  iniciais: iniciais.slice(0, 2),
  msg_carimbo: txt(campo('msg_carimbo'), 70) || 'Carimbo garantido! 🎉',
  msg_premio: txt(campo('msg_premio'), 110) || `Cartão completo! Seu prêmio: ${d.premio}.`,
  avisos: {
    quase,
    saudade: aviso(campo('aviso_saudade'), { titulo: '👋 Que saudade!', texto: `Faz tempo que você não aparece na ${d.nome}. Seu cartão está te esperando!` }),
    // sem presente de aniversário informado pelo dono, não existe aviso de aniversário (a IA não pode inventar brinde)
    aniversario: d.aniversario ? aviso(campo('aviso_aniversario'), { titulo: '🎂 Feliz aniversário!', texto: `Seu presente te espera na ${d.nome}: ${d.aniversario}.` }) : null,
  },
  whatsapp: d.whatsapp, instagram: d.instagram, endereco: d.endereco,
  vapid: { publica: b64u(Buffer.concat([Buffer.from([4]), unb(pub.x), unb(pub.y)])), privada: { kty: 'EC', crv: 'P-256', d: jwk.d, x: jwk.x, y: jwk.y } },
};
return [{ json: { id: programa.id, programa: JSON.stringify(programa) } }];

// Desenha o cartão fidelidade (o app que o cliente instala). A página é igual para todos: quem é o cliente fica guardado no celular (código + token) e o cartão vem da API.
let p = null;
try { p = JSON.parse($('📖 Lê o programa (cartão GET)').first().json.programa || 'null'); } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
if (!p) {
  return [{ json: { codigo: 404, html: `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cartão não encontrado</title></head>
<body style="font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#f6f6f4;color:#222;text-align:center;padding:24px">
<div><div style="font-size:56px">🎟️</div><h1 style="font-size:22px">Cartão não encontrado</h1><p style="color:#666">Confira o link ou leia de novo o QR do balcão.</p></div></body></html>` } }];
}

// Cores derivadas da cor do negócio, com contraste garantido no claro e no escuro
const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
const paraHex = a => '#' + a.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
const mistura = (c, alvo, t) => paraHex(hex(c).map((v, i) => v + (alvo[i] - v) * t));
const lum = c => { const [r, g, b] = hex(c).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
const contraste = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const C = p.cor;
const legivel = (fundo, para, alvo = 4.5) => { let x = C; for (let t = 0.05; t <= 1.01 && contraste(x, fundo) < alvo; t += 0.05) x = mistura(C, para, t); return x; };
const corTexto = lum(C) > 0.45 ? '#111111' : '#ffffff';
const C2 = mistura(C, [0, 0, 0], 0.35), CL = mistura(C, [255, 255, 255], 0.88), CLd = mistura(C, [0, 0, 0], 0.6);
const destaqueClaro = legivel('#ffffff', [0, 0, 0]), destaqueEscuro = legivel('#1b1b1d', [255, 255, 255]);
const botaoEscuro = contraste(C, '#1b1b1d') < 3 ? legivel('#1b1b1d', [255, 255, 255], 8) : C;
const textoBotaoEscuro = lum(botaoEscuro) > 0.45 ? '#111111' : '#ffffff';
const wa = p.whatsapp ? `https://wa.me/${p.whatsapp}?text=${encodeURIComponent('Olá! Vim pelo cartão fidelidade da ' + p.nome + '.')}` : '';
const mapa = p.endereco ? 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(p.endereco) : '';
const contatos = [wa && ['💬', 'WhatsApp', wa], p.instagram && ['📸', 'Instagram', 'https://instagram.com/' + p.instagram], mapa && ['📍', 'Como chegar', mapa]].filter(Boolean);

// Este código roda no celular do cliente (vai como texto com .toString()).
function cliente(P) {
  var el = function (s) { return document.querySelector(s); };
  var API = '/webhook/fidelidade-api', CHAVE = 'fid-' + P.id;
  var eu = null, est = null, espera = null, lendo = null;
  try { eu = JSON.parse(localStorage.getItem(CHAVE) || 'null'); } catch (e) {}
  var qs = new URLSearchParams(location.search), qr = qs.get('c') || '';
  if (qr) history.replaceState(null, '', location.pathname);  // o código do QR não fica no endereço (nem no histórico)
  var standalone = matchMedia('(display-mode: standalone)').matches || navigator.standalone === true;
  var ios = /iphone|ipad|ipod/i.test(navigator.userAgent);

  function toast(t, longo) { var x = el('#toast'); x.textContent = t; x.classList.add('on'); clearTimeout(x._t); x._t = setTimeout(function () { x.classList.remove('on'); }, longo ? 6000 : 3500); }
  function api(dados) {
    return fetch(API, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(Object.assign({ id: P.id }, eu ? { cid: eu.cid, token: eu.token } : {}, dados)) })
      .then(function (r) { return r.json(); }).catch(function () { return { ok: false, erro: 'Sem conexão agora. Tente de novo.' }; });
  }
  function guarda(r) { eu = { cid: r.cid, token: r.token }; try { localStorage.setItem(CHAVE, JSON.stringify(eu)); } catch (e) {} }
  function sai() { eu = null; est = null; try { localStorage.removeItem(CHAVE); } catch (e) {} mostra('cadastro'); }
  function mostra(t) { el('#tela-cadastro').hidden = t !== 'cadastro'; el('#tela-cartao').hidden = t !== 'cartao'; }
  function quando(ms) { return new Date(ms).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }); }
  var NOMES = { cadastro: '🎟️ Cartão criado', carimbo: P.emoji + ' Carimbo', premio: '🎁 Cartão completo', resgate: '✅ Prêmio retirado' };

  function desenha(e, novo) {
    var antes = est; est = e; mostra('cartao');
    el('#ola').textContent = 'Olá, ' + String(e.nome || '').split(' ')[0] + '!';
    var html = '';
    for (var i = 0; i < e.meta; i++) {
      var cheio = i < e.carimbos;
      html += '<span class="selo' + (cheio ? ' cheio' : '') + (novo && i === e.carimbos - 1 ? ' novo' : '') + '" aria-label="' + (cheio ? 'carimbo ' + (i + 1) : 'falta') + '">' + (cheio ? P.emoji : (i + 1)) + '</span>';
    }
    el('#selos').innerHTML = html;
    var faltam = e.meta - e.carimbos;
    el('#conta').textContent = e.carimbos + ' de ' + e.meta;
    el('#faltam').textContent = e.premios > 0 && e.carimbos === 0 ? 'Cartão novo começando' : (faltam === 1 ? 'Falta 1 carimbo' : 'Faltam ' + faltam + ' carimbos') + ' para ' + P.premio;
    el('#barra i').style.width = Math.round(e.carimbos / e.meta * 100) + '%';
    el('#premio').hidden = e.premios < 1;
    el('#premio-txt').textContent = (e.premios > 1 ? 'Você tem ' + e.premios + ' prêmios: ' : 'Você ganhou: ') + P.premio;
    el('#pendente').hidden = !e.pendente;
    el('#bt-resgatar').hidden = !!e.pendente;
    if (e.pendente) el('#codigo').textContent = e.pendente.codigo;
    el('#proximo').hidden = !(e.proximo_em > Date.now());
    if (e.proximo_em > Date.now()) el('#proximo').textContent = '⏱️ Próximo carimbo a partir de ' + quando(e.proximo_em);
    el('#historico').innerHTML = (e.historico || []).map(function (h) { return '<li><span>' + (NOMES[h.e] || h.e) + '</span><time>' + quando(h.t) + '</time></li>'; }).join('');
    el('#total').textContent = e.total + (e.total === 1 ? ' carimbo' : ' carimbos') + ' no total · ' + e.resgatados + (e.resgatados === 1 ? ' prêmio retirado' : ' prêmios retirados');
    // resgate esperando o balcão: confere a cada 4 s até o atendente confirmar
    if (e.pendente && !espera) espera = setInterval(atualiza, 4000);
    if (!e.pendente && espera) { clearInterval(espera); espera = null; if (antes && antes.pendente && e.resgatados > antes.resgatados) festa('✅ Prêmio entregue! Aproveite 🎉'); }
    if (antes && e.premios > antes.premios) festa(P.msg_premio);
  }
  function festa(t) { el('#festa').classList.remove('on'); void el('#festa').offsetWidth; el('#festa').classList.add('on'); toast(t, true); if (navigator.vibrate) navigator.vibrate([60, 40, 120]); }
  function atualiza() { if (!eu) return; api({ acao: 'estado' }).then(function (r) { if (r.ok) desenha(r.estado); else if (r.sair) sai(); }); }
  function carimba(c) {
    toast('⏳ Carimbando…');
    api({ acao: 'carimbar', c: c }).then(function (r) {
      if (r.sair) { sai(); toast(r.erro, true); return; }
      if (r.estado) desenha(r.estado, r.ok);
      if (r.ok) { if (!(est && est.carimbos === 0 && est.premios > 0)) toast(P.msg_carimbo); if (navigator.vibrate) navigator.vibrate(80); } else toast(r.erro, true);
    });
  }

  // ── leitor de QR dentro do cartão (BarcodeDetector no Android; jsQR no iPhone e onde não houver) ──
  function carregaJsQR() {
    return window.jsQR ? Promise.resolve() : new Promise(function (ok, falha) {
      var s = document.createElement('script'); s.src = 'https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js'; s.onload = ok; s.onerror = falha; document.head.appendChild(s);
    });
  }
  function fechaLeitor() {
    el('#leitor').hidden = true;
    if (lendo && lendo.stream) lendo.stream.getTracks().forEach(function (t) { t.stop(); });
    lendo = null;
  }
  function abreLeitor(depois) {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { toast('Use a câmera do celular para ler o QR do balcão.', true); return; }
    el('#leitor').hidden = false; el('#leitor-msg').textContent = 'Aponte para o QR que está na tela do balcão';
    var v = el('#video'), cv = document.createElement('canvas'), ctx = cv.getContext('2d', { willReadFrequently: true });
    var det = 'BarcodeDetector' in window ? new window.BarcodeDetector({ formats: ['qr_code'] }) : null;
    lendo = { stream: null };
    var meu = lendo;
    navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' }, audio: false }).then(function (st) {
      if (meu !== lendo) { st.getTracks().forEach(function (t) { t.stop(); }); return; }
      lendo.stream = st; v.srcObject = st; v.setAttribute('playsinline', ''); return v.play().then(function () { return det ? null : carregaJsQR(); });
    }).then(function () {
      function trata(texto) {
        var m = String(texto || '').match(/\/fidelidade\/([a-z0-9-]+)\/cartao\?c=(\d+\.[a-f0-9]{10})/);
        if (!m) { el('#leitor-msg').textContent = 'Esse QR não é o do balcão. Procure o QR que muda na tela.'; return false; }
        if (m[1] !== P.id) { el('#leitor-msg').textContent = 'Esse QR é de outro estabelecimento.'; return false; }
        fechaLeitor(); depois(m[2]); return true;
      }
      (function passo() {
        if (meu !== lendo) return;
        if (v.readyState >= 2) {
          if (det) { det.detect(v).then(function (cs) { if (!(cs[0] && trata(cs[0].rawValue))) setTimeout(passo, 250); }).catch(function () { setTimeout(passo, 400); }); return; }
          cv.width = v.videoWidth; cv.height = v.videoHeight; ctx.drawImage(v, 0, 0);
          var q = window.jsQR(ctx.getImageData(0, 0, cv.width, cv.height).data, cv.width, cv.height, { inversionAttempts: 'dontInvert' });
          if (q && trata(q.data)) return;
        }
        setTimeout(passo, 250);
      })();
    }).catch(function () { fechaLeitor(); toast('Não deu para abrir a câmera aqui. Libere a câmera ou use o app de câmera do celular para ler o QR.', true); });
  }
  el('#bt-fechar-leitor').addEventListener('click', fechaLeitor);
  el('#bt-ler').addEventListener('click', function () { abreLeitor(carimba); });

  // ── cadastro e recuperação ──
  function cadastra(ev) {
    ev.preventDefault();
    var bt = el('#bt-criar'); bt.disabled = true; bt.textContent = '⏳ Criando…';
    api({ acao: 'cadastrar', nome: el('#nome').value, fone: el('#fone').value, aniversario: el('#aniv').value, c: qr }).then(function (r) {
      bt.disabled = false; bt.textContent = '🎟️ Criar meu cartão';
      if (!r.ok) { el('#erro').textContent = r.erro || 'Não deu para criar agora.'; if (r.recuperar) el('#recuperar').open = true; return; }
      guarda(r); qr = ''; desenha(r.estado, r.carimbou);
      toast(r.recuperado ? 'Achamos seu cartão! ' + (r.carimbou ? 'E o carimbo de hoje já entrou.' : (r.aviso || '')) : (r.carimbou ? 'Cartão criado e o 1º carimbo já entrou! 🎉' : P.boas_vindas), true);
    });
  }
  el('#form').addEventListener('submit', cadastra);
  el('#bt-recuperar').addEventListener('click', function () {
    var fone = el('#fone-rec').value;
    if (String(fone).replace(/\D/g, '').length < 10) { el('#erro-rec').textContent = 'Digite o WhatsApp com DDD.'; return; }
    function tenta(c) {
      api({ acao: 'recuperar', fone: fone, c: c }).then(function (r) {
        if (!r.ok) { el('#erro-rec').textContent = r.erro; return; }
        guarda(r); qr = ''; desenha(r.estado, r.carimbou); toast('Cartão recuperado neste celular! 🎉', true);
      });
    }
    if (qr) tenta(qr); else abreLeitor(tenta);
  });
  el('#bt-trocar').addEventListener('click', function () { if (confirm('Tirar o cartão deste celular? Ele continua guardado; para voltar, use "Já tenho cartão" com o QR do balcão.')) sai(); });

  // ── resgate ──
  el('#bt-resgatar').addEventListener('click', function () {
    api({ acao: 'resgatar' }).then(function (r) { if (r.estado) desenha(r.estado); if (!r.ok) toast(r.erro, true); else toast('Mostre o código para o atendente. 👀', true); });
  });

