// Monta o service worker: o "motor" do cartão no celular (abre sem internet e mostra os avisos).
const id = String(($('🔔 Pedido do motor (GET)').first().json.params || {}).id || '').replace(/[^a-z0-9-]/g, '');

function motor(ID) {
  var CACHE = 'fid-' + ID + '-v1';
  var TELAS = ['cartao', 'manifesto', 'simbolo?t=192', 'simbolo?t=512'];
  self.addEventListener('install', function (e) {
