// Calcula o ícone: fundo na cor do negócio + iniciais centralizadas ("m=1" = ícone que o Android recorta em círculo: letras menores).
const q = $('🔔 Pedido do ícone (GET)').first().json.query || {};
let p = null;
try { p = JSON.parse($('📖 Lê o programa (ícone)').first().json.programa || 'null'); } catch (e) {}
const t = [96, 144, 180, 192, 512].includes(Number(q.t)) ? Number(q.t) : 192;
const recorte = q.m === '1';
const ini = (p ? p.iniciais : '?').slice(0, 2);
const fonte = Math.round(t * (recorte ? 0.3 : 0.4) * (ini.length === 1 ? 1.15 : 1));
