if (fone.length >= 10 && fone.length <= 11) fone = '55' + fone;
const aniv = String(b.aniversario || '').match(/^(\d{1,2})\/(\d{1,2})$/);
const aniversario = aniv && +aniv[1] >= 1 && +aniv[1] <= 31 && +aniv[2] >= 1 && +aniv[2] <= 12 ? aniv[1].padStart(2, '0') + '/' + aniv[2].padStart(2, '0') : '';
return [{ json: { acao: ACOES.includes(b.acao) && id ? b.acao : 'invalida', id, cid, token: String(b.token || '').slice(0, 64), fone, aniversario,
  nome: limpa(b.nome, 40), c: String(b.c || '').slice(0, 40), sub: b.sub && typeof b.sub === 'object' ? b.sub : null,
  k_programa: 'fid:' + (id || '-'), k_fone: 'fidt:' + (id || '-') + ':' + (fone || '-') } }];

// O coração do cartão: confere quem é o cliente, valida o QR do balcão e decide o que gravar. Sempre responde com o estado do cartão.
const crypto = require('crypto');
const P = $('🧩 Lê o pedido do cartão').first().json;
let prog = null, cli = null, pend = null;
try { prog = JSON.parse($('📖 Lê o programa (cartão)').first().json.programa || 'null'); } catch (e) {}
try { cli = JSON.parse($('📖 Lê o cliente (cartão)').first().json.cliente || 'null'); } catch (e) {}
try { pend = JSON.parse($('📖 Lê o resgate pendente').first().json.resgate || 'null'); } catch (e) {}
const indice = String($('📖 Lê o telefone').first().json.indice || '');
const agora = Date.now();
const dia = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const ANO = 31536000;
const sets = [], somas = [];
const sai = (codigo, corpo) => [{ json: { codigo, resposta: JSON.stringify(corpo), sets, somas, id: P.id, dia } }];
