if (!prog) return erro('Programa de fidelidade não encontrado. Confira o link.', 404);
if (P.acao === 'invalida') return erro('Pedido inválido.');
const hmac = t => crypto.createHmac('sha256', prog.segredo).update(t).digest('hex');
const tokenDe = cid => hmac('cli:' + cid).slice(0, 24);

// QR do balcão = "<janela de 30 s>.<assinatura>". Vale a janela atual e as 3 anteriores (até 2 min para quem demora a ler).
function codigoOk(c) {
  const m = String(c || '').match(/^(\d{6,12})\.([a-f0-9]{10})$/);
  if (!m) return false;
  const janela = Number(m[1]), atual = Math.floor(agora / 30000);
