}
function estado(c) {
  return { nome: c.nome, carimbos: c.carimbos, meta: prog.meta, premios: c.premios, resgatados: c.resgatados, total: c.total,
    historico: c.historico.slice(0, 12), pendente: pend && pend.cid === c.cid ? { codigo: pend.codigo } : null,
