    if (!codigoOk(P.c)) return erro(P.acao === 'cadastrar' ? 'Esse WhatsApp já tem cartão aqui. Para recuperar, leia o QR do balcão.' : 'Para recuperar o cartão, leia o QR que está na tela do balcão.', 409, { recuperar: true });
