    carimbos: 0, premios: 0, resgatados: 0, total: 0, ultimo_carimbo: 0, ultimo_codigo: '', historico: [{ t: agora, e: 'cadastro' }] };
  const msg = P.c ? carimba(c, P.c) : '';
  guarda(c);
  sets.push({ chave: `fidt:${prog.id}:${P.fone}`, valor: c.cid, ttl: ANO });
  somas.push(`fidst:${prog.id}:novos:${dia}`);
  return sai(200, { ok: true, cid: c.cid, token: tokenDe(c.cid), carimbou: !!P.c && !msg, aviso: msg, estado: estado(c) });
}

// daqui para baixo o celular já tem cartão: o token prova que é dele
if (!cli || !P.cid || P.token !== tokenDe(P.cid)) return erro('Cartão não encontrado neste celular. Crie ou recupere o cartão.', 401, { sair: true });
if (P.acao === 'estado') return sai(200, { ok: true, estado: estado(cli) });

if (P.acao === 'carimbar') {
  const msg = carimba(cli, P.c);
  if (msg) return erro(msg, 400, { estado: estado(cli) });
  guarda(cli);
  return sai(200, { ok: true, carimbou: true, estado: estado(cli) });
}

if (P.acao === 'resgatar') {
  if (cli.premios < 1) return erro('Você ainda não tem prêmio para resgatar.', 400, { estado: estado(cli) });
