    pend = { cid: cli.cid, nome: cli.nome, codigo: String(crypto.randomInt(1000, 10000)), criado: agora };
    sets.push({ chave: `fidr:${prog.id}:${cli.cid}`, valor: JSON.stringify(pend), ttl: 1800 });
    somas.push(`fidst:${prog.id}:pedidos_resgate:${dia}`);
