  return sai(200, { ok: true, estado: estado(cli) });
}
return erro('Pedido inválido.');

// sempre ao menos 1 soma, para o fluxo seguir até a resposta
const d = $('🎟️ Decide o cartão').first().json;
return (d.somas.length ? d.somas : [`fidst:${d.id}:uso:${d.dia}`]).map(chave => ({ json: { chave } }));

// Tela do balcão (tablet ou celular do dono): QR que muda a cada 30 s para o cliente carimbar + prêmios esperando o atendente confirmar.
const q = $('🔔 Abrir balcão (GET)').first().json.query || {};
let p = null;
try { p = JSON.parse($('📖 Lê o programa (balcão)').first().json.programa || 'null'); } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
if (!p || String(q.chave || '') !== p.chave) {
  return [{ json: { codigo: 403, html: `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Balcão</title><meta name="robots" content="noindex"></head>
<body style="font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#f6f6f4;color:#222;text-align:center;padding:24px">
<div><div style="font-size:56px">🔒</div><h1 style="font-size:22px">Link do balcão inválido</h1><p style="color:#666">Abra o balcão pelo link do painel do dono.</p></div></body></html>` } }];
}
const lum = c => { const v = [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16) / 255).map(x => x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4)); return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2]; };
