  function buscaQR() {
    api({ acao: 'codigo' }).then(function (r) {
      if (!r.ok) { el('#estado').textContent = '⚠️ ' + (r.erro || 'Não deu para gerar o QR.') + ' Tentando de novo…'; setTimeout(buscaQR, 5000); return; }
