Object.entries($('🗂️ Lê os clientes (dono)').first().json || {}).forEach(([k, v]) => {
  if (k.startsWith(`fidc:${prog.id}:`)) { try { const c = JSON.parse(v); clientes[c.cid] = c; } catch (e) {} }
});
const alvos = Object.entries($('🗂️ Lê os inscritos (dono)').first().json || {}).filter(([k]) => k.startsWith(`fidpush:${prog.id}:`)).map(([chave, v]) => {
  let sub = null;
  try { sub = JSON.parse(v); } catch (e) {}
  const c = clientes[chave.split(':')[2]];
  return sub && sub.endpoint && c && noGrupo(c, P.grupo, prog, agora) ? { chave, sub, c } : null;
}).filter(Boolean);
// inscrição com chave quebrada não derruba o envio dos outros: é pulada e sai da lista junto com quem desinstalou
const saida = [], invalidos = [];
for (const { chave, sub, c } of alvos) {
  try {
    saida.push({ json: { chave, cid: c.cid, endpoint: sub.endpoint, autorizacao: vapid(prog, sub.endpoint) },
      binary: { corpo: { data: criptografa(sub, JSON.stringify({ titulo: pers(P.titulo, c, prog), texto: pers(P.texto, c, prog), url: 'cartao', tag: 'aviso-' + agora })).toString('base64'),
        mimeType: 'application/octet-stream', fileName: 'aviso.bin' } } });
  } catch (e) { invalidos.push(chave); }
}
if (!saida.length) return [{ json: { vazio: true, invalidos } }];
saida[0].json.invalidos = invalidos;
return saida;

// Conta quantos celulares receberam. 201 = entregue · 404/410 = a pessoa desinstalou ou desligou os avisos (sai da lista).
