  var COLS = [['nome', 'Cliente'], ['fone', 'WhatsApp'], ['carimbos', 'Carimbos'], ['premios', 'Prêmio esperando'], ['resgatados', 'Retirados'], ['total', 'Total'], ['ultima', 'Última visita'], ['criado', 'Desde'], ['aniversario', 'Aniversário'], ['avisos', 'Avisos']];
  function filtradas() {
    var q = busca.toLowerCase();
    return D.linhas.filter(function (l) { return (!filtroG || l.grupos.indexOf(filtroG) > -1) && (!q || (l.nome + ' ' + l.fone).toLowerCase().indexOf(q) > -1); })
      .sort(function (a, b) { var x = a[ordem.campo], y = b[ordem.campo]; return (x > y ? 1 : x < y ? -1 : 0) * ordem.dir; });
  }
  function tabela() {
    var ls = filtradas();
    el('#thead').innerHTML = '<tr>' + COLS.map(function (c) { return '<th><button data-campo="' + c[0] + '">' + c[1] + (ordem.campo === c[0] ? (ordem.dir > 0 ? ' ▲' : ' ▼') : '') + '</button></th>'; }).join('') + '</tr>';
    el('#tbody').innerHTML = ls.map(function (l) {
      return '<tr><td><b>' + l.nome.replace(/[<>&]/g, '') + '</b>' + l.grupos.map(function (g) { return '<span class="tag">' + NOMES_G[g] + '</span>'; }).join('') + '</td>'
        + '<td><a href="https://wa.me/' + l.fone + '" target="_blank" rel="noopener">' + fone(l.fone) + '</a></td>'
        + '<td>' + l.carimbos + '/' + D.meta + '</td><td>' + (l.premios ? '🎁 ' + l.premios : '—') + '</td><td>' + l.resgatados + '</td><td>' + l.total + '</td>'
        + '<td>' + data(l.ultima) + '</td><td>' + data(l.criado) + '</td><td>' + (l.aniversario || '—') + '</td><td>' + (l.avisos ? '✅' : '—') + '</td></tr>';
    }).join('') || '<tr><td colspan="10" class="vazio">' + (D.linhas.length ? 'Ninguém com esse filtro.' : 'Nenhum cliente ainda. Ponha o QR do balcão à vista e o primeiro aparece aqui.') + '</td></tr>';
    el('#qtd').textContent = ls.length + ' de ' + D.linhas.length + ' clientes';
  }
  el('#thead').addEventListener('click', function (e) { var b = e.target.closest('button[data-campo]'); if (!b) return; ordem = { campo: b.dataset.campo, dir: ordem.campo === b.dataset.campo ? -ordem.dir : (b.dataset.campo === 'nome' ? 1 : -1) }; tabela(); });
  el('#busca').addEventListener('input', function () { busca = this.value; tabela(); });
  el('#chips').addEventListener('click', function (e) {
    var b = e.target.closest('button[data-g]'); if (!b) return;
    filtroG = filtroG === b.dataset.g ? '' : b.dataset.g;
