  });
  el('#csv').addEventListener('click', function () {
    var cab = ['nome', 'whatsapp', 'carimbos', 'premios_esperando', 'retirados', 'total', 'ultima_visita', 'desde', 'aniversario', 'avisos_ligados', 'grupos'];
    var q = function (v) { v = String(v == null ? '' : v); return /[",;\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; };
