return [{ json: { codigo: 200, html } }];

// Web Push: a mensagem vai criptografada só para aquele celular (RFC 8291) e assinada com a chave do programa (VAPID, RFC 8292).
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
function criptografa(sub, texto) {
  const cr = require('crypto');
  const uaPublica = unb(sub.keys.p256dh), segredo = unb(sub.keys.auth);
  const ecdh = cr.createECDH('prime256v1'); ecdh.generateKeys();
  const asPublica = ecdh.getPublicKey();
  const compartilhado = ecdh.computeSecret(uaPublica);
  const sal = cr.randomBytes(16);
  const info = Buffer.concat([Buffer.from('WebPush: info\0'), uaPublica, asPublica]);
  const ikm = Buffer.from(cr.hkdfSync('sha256', compartilhado, segredo, info, 32));
  const cek = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
  const nonce = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: nonce\0'), 12));
  const c = cr.createCipheriv('aes-128-gcm', cek, nonce);
  const cifrado = Buffer.concat([c.update(Buffer.concat([Buffer.from(texto, 'utf8'), Buffer.from([2])])), c.final(), c.getAuthTag()]);
  const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
  return Buffer.concat([sal, rs, Buffer.from([asPublica.length]), asPublica, cifrado]);
}
function vapid(prog, endpoint) {
  const cr = require('crypto');
  const cab = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  // "aud" = endereço do serviço de avisos (Google, Apple ou Mozilla); o Code node não tem URL(), então recorto o texto
  const corpo = b64u(JSON.stringify({ aud: (String(endpoint).match(/^https:\/\/[^/]+/) || [''])[0], exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: 'https://webhookn8n6.inovareinteligenciaartificial.com' }));
  const assinatura = cr.sign('sha256', Buffer.from(cab + '.' + corpo), { key: cr.createPrivateKey({ key: prog.vapid.privada, format: 'jwk' }), dsaEncoding: 'ieee-p1363' });
  return `vapid t=${cab}.${corpo}.${b64u(assinatura)}, k=${prog.vapid.publica}`;
}
// {nome} = primeiro nome do cliente · {faltam} = carimbos que faltam para o prêmio
const pers = (t, c, prog) => String(t || '').replace(/\{nome\}/g, String(c.nome || '').split(' ')[0]).replace(/\{faltam\}/g, Math.max(1, prog.meta - c.carimbos));

// Avisos automáticos do dia, por programa: aniversário (com o presente do dono), prêmio esperando, quase lá e saudade.
// No máximo 1 aviso por cliente por dia, e cada tipo tem seu intervalo para não virar chateação.
const progs = $('📖 Lê o programa (diário)').all(), clis = $('🗂️ Lê os clientes (diário)').all(), subs = $('🗂️ Lê os inscritos (diário)').all();
const agora = Date.now(), DIA = 86400000;
const hoje = new Date(agora).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit' });
const ano = new Date(agora).toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' }).slice(0, 4);
const saida = [];
progs.forEach((pi, i) => {
  let prog = null;
  try { prog = JSON.parse(pi.json.programa || 'null'); } catch (e) {}
  if (!prog || !prog.vapid) return;
  const inscritos = {};
  Object.entries((subs[i] || {}).json || {}).forEach(([k, v]) => {
    if (k.startsWith(`fidpush:${prog.id}:`)) { try { inscritos[k.split(':')[2]] = { chave: k, sub: JSON.parse(v) }; } catch (e) {} }
  });
  Object.entries((clis[i] || {}).json || {}).forEach(([k, v]) => {
    if (!k.startsWith(`fidc:${prog.id}:`)) return;
    let c = null;
    try { c = JSON.parse(v); } catch (e) {}
    const s = c && inscritos[c.cid];
    if (!s || !s.sub || !s.sub.endpoint) return;
    const parado = (agora - (c.ultimo_carimbo || c.criado || 0)) / DIA;
    let tipo = null;
    if (prog.avisos.aniversario && c.aniversario === hoje && c.aviso_aniv !== ano) { tipo = 'aniversario'; c.aviso_aniv = ano; }
    else if (c.premios > 0 && parado >= 3 && (!c.aviso_premio || agora - c.aviso_premio > 7 * DIA)) { tipo = 'premio'; c.aviso_premio = agora; }
    else if (c.premios === 0 && c.carimbos > 0 && prog.meta - c.carimbos <= 2 && parado >= 5 && (!c.aviso_quase || agora - c.aviso_quase > 14 * DIA)) { tipo = 'quase'; c.aviso_quase = agora; }
    else if (prog.dias_saudade > 0 && parado >= prog.dias_saudade && (!c.aviso_saudade || agora - c.aviso_saudade > 30 * DIA)) { tipo = 'saudade'; c.aviso_saudade = agora; }
    if (!tipo) return;
    const a = tipo === 'premio' ? { titulo: '🎁 Seu prêmio está esperando', texto: `Você completou o cartão da ${prog.nome}: ${prog.premio}. Passe aqui para retirar!` } : prog.avisos[tipo];
    try {  // inscrição com chave quebrada é pulada (não derruba os avisos dos outros clientes)
      saida.push({
        json: { tipo, prog_id: prog.id, cid: c.cid, chave_push: s.chave, chave_cliente: k, cliente: JSON.stringify(c), endpoint: s.sub.endpoint, autorizacao: vapid(prog, s.sub.endpoint) },
        binary: { corpo: { data: criptografa(s.sub, JSON.stringify({ titulo: pers(a.titulo, c, prog), texto: pers(a.texto, c, prog), url: 'cartao', tag: tipo })).toString('base64'),
          mimeType: 'application/octet-stream', fileName: 'aviso.bin' } },
      });
    } catch (e) {}
  });
});
return saida;

// 201 = entregue: grava no cliente a data do aviso (para não repetir) · 404/410 = desinstalou: tira o celular da lista.
const envios = $('🔐 Escolhe quem avisar').all();
return $input.all().map((r, i) => {
  const st = Number(r.json.statusCode || 0), e = (envios[i] || {}).json || {};
  if (st >= 200 && st < 300 && e.chave_cliente) return { json: { op: 'gravar', chave: e.chave_cliente, valor: e.cliente } };
  if ((st === 404 || st === 410) && e.chave_push) return { json: { op: 'apagar', chave: e.chave_push } };
  return null;
}).filter(Boolean);

// O fluxo responde na hora com os links; as IAs continuam escrevendo os textos em segundo plano.
const r = $input.first().json;
if (!r.ok) throw new Error('A criação recusou o teste: ' + (r.erros || [r.message || 'sem resposta']).join(' '));
return [{ json: { id: r.id, chave: (String(r.painel_url).match(/chave=([a-f0-9]+)/) || [])[1], cartao_url: r.cartao_url, balcao_url: r.balcao_url, painel_url: r.painel_url } }];

// o celular da cliente guarda o código e o token do cartão (é assim que o cartão sabe quem é ela)
const r = $input.first().json;
if (!r.ok) throw new Error('O cartão da cliente não foi criado: ' + r.erro);
return [{ json: { cid: r.cid, token: r.token, carimbos: r.estado.carimbos, carimbou: r.carimbou } }];

// tudo certo = mostra o cartão final e os links · algo errado = o node fica vermelho com o motivo
const l = $('👉 Guarda os links').first().json, fim = $input.first().json, ent = $('🌐 Balcão entrega o prêmio').first().json;
const pedido = $('🌐 Cliente pede o prêmio').first().json, pend = $('🌐 Balcão vê os pedidos').first().json;
if (!pedido.ok) throw new Error('A cliente não conseguiu pedir o prêmio (não completou o cartão?): ' + pedido.erro);
if (!ent.ok) throw new Error('O balcão não conseguiu entregar o prêmio: ' + ent.erro);
const e = fim.estado || {};
if (e.resgatados !== 1 || e.premios !== 0) throw new Error('O cartão final não fechou a conta: ' + JSON.stringify(e));
return [{ json: { '✅': `Programa criado, ${e.total} carimbos, prêmio pedido e entregue no balcão`, '📲 cartão do cliente': l.cartao_url,
  '🖥️ balcão (tablet do caixa)': l.balcao_url, '📊 painel do dono': l.painel_url,
  '🎟️ cartão final': `${e.carimbos}/${e.meta} carimbos · ${e.resgatados} prêmio retirado`, '🗒️ histórico': (e.historico || []).map(h => h.e).join(' → '),
