if (fone.length >= 10 && fone.length <= 11) fone = '55' + fone;
const aniv = String(b.aniversario || '').match(/^(\d{1,2})\/(\d{1,2})$/);
const aniversario = aniv && +aniv[1] >= 1 && +aniv[1] <= 31 && +aniv[2] >= 1 && +aniv[2] <= 12 ? aniv[1].padStart(2, '0') + '/' + aniv[2].padStart(2, '0') : '';
return [{ json: { acao: ACOES.includes(b.acao) && id ? b.acao : 'invalida', id, cid, token: String(b.token || '').slice(0, 64), fone, aniversario,
  nome: limpa(b.nome, 40), c: String(b.c || '').slice(0, 40), sub: b.sub && typeof b.sub === 'object' ? b.sub : null,
  k_programa: 'fid:' + (id || '-'), k_fone: 'fidt:' + (id || '-') + ':' + (fone || '-') } }];

// O coração do cartão: confere quem é o cliente, valida o QR do balcão e decide o que gravar. Sempre responde com o estado do cartão.
const crypto = require('crypto');
const P = $('🧩 Lê o pedido do cartão').first().json;
let prog = null, cli = null, pend = null;
try { prog = JSON.parse($('📖 Lê o programa (cartão)').first().json.programa || 'null'); } catch (e) {}
try { cli = JSON.parse($('📖 Lê o cliente (cartão)').first().json.cliente || 'null'); } catch (e) {}
try { pend = JSON.parse($('📖 Lê o resgate pendente').first().json.resgate || 'null'); } catch (e) {}
const indice = String($('📖 Lê o telefone').first().json.indice || '');
const agora = Date.now();
const dia = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const ANO = 31536000;
const sets = [], somas = [];
const sai = (codigo, corpo) => [{ json: { codigo, resposta: JSON.stringify(corpo), sets, somas, id: P.id, dia } }];
const erro = (msg, codigo = 400, extra = {}) => sai(codigo, { ok: false, erro: msg, ...extra });

if (!prog) return erro('Programa de fidelidade não encontrado. Confira o link.', 404);
if (P.acao === 'invalida') return erro('Pedido inválido.');
const hmac = t => crypto.createHmac('sha256', prog.segredo).update(t).digest('hex');
const tokenDe = cid => hmac('cli:' + cid).slice(0, 24);

// QR do balcão = "<janela de 30 s>.<assinatura>". Vale a janela atual e as 3 anteriores (até 2 min para quem demora a ler).
function codigoOk(c) {
  const m = String(c || '').match(/^(\d{6,12})\.([a-f0-9]{10})$/);
  if (!m) return false;
  const janela = Number(m[1]), atual = Math.floor(agora / 30000);
  return janela <= atual && atual - janela <= 3 && hmac('qr:' + janela).slice(0, 10) === m[2];
}
function estado(c) {
  return { nome: c.nome, carimbos: c.carimbos, meta: prog.meta, premios: c.premios, resgatados: c.resgatados, total: c.total,
    historico: c.historico.slice(0, 12), pendente: pend && pend.cid === c.cid ? { codigo: pend.codigo } : null,
    proximo_em: prog.intervalo_h > 0 && c.ultimo_carimbo ? c.ultimo_carimbo + prog.intervalo_h * 3600000 : 0 };
}
// devolve '' se carimbou, ou o motivo de não carimbar
function carimba(c, codigo) {
  if (!codigoOk(codigo)) return 'Esse QR já venceu. Leia o QR que está agora na tela do balcão.';
  if (c.ultimo_codigo === codigo) return 'Esse QR já carimbou seu cartão. Espere o próximo aparecer no balcão.';
  if (prog.intervalo_h > 0 && c.ultimo_carimbo && agora - c.ultimo_carimbo < prog.intervalo_h * 3600000) {
    const quando = new Date(c.ultimo_carimbo + prog.intervalo_h * 3600000).toLocaleString('pt-BR', { hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit', timeZone: 'America/Sao_Paulo' });
