}
const guarda = c => sets.push({ chave: `fidc:${prog.id}:${c.cid}`, valor: JSON.stringify(c), ttl: ANO });

if (P.acao === 'cadastrar' || P.acao === 'recuperar') {
  if (P.fone.length < 12) return erro('Digite seu WhatsApp com DDD.');
  if (indice && cli) {
    // esse WhatsApp já tem cartão: só devolve para quem está com o QR do balcão na mão (prova de que está na loja)
    if (!codigoOk(P.c)) return erro(P.acao === 'cadastrar' ? 'Esse WhatsApp já tem cartão aqui. Para recuperar, leia o QR do balcão.' : 'Para recuperar o cartão, leia o QR que está na tela do balcão.', 409, { recuperar: true });
    const msg = carimba(cli, P.c);
    guarda(cli);
    return sai(200, { ok: true, cid: cli.cid, token: tokenDe(cli.cid), recuperado: true, carimbou: !msg, aviso: msg, estado: estado(cli) });
  }
  if (P.acao === 'recuperar') return erro('Não achei cartão com esse WhatsApp. Crie um cartão novo.', 404);
  if (P.nome.length < 2) return erro('Digite seu nome.');
  const c = { cid: crypto.randomBytes(6).toString('hex'), nome: P.nome, fone: P.fone, aniversario: P.aniversario, criado: agora,
    carimbos: 0, premios: 0, resgatados: 0, total: 0, ultimo_carimbo: 0, ultimo_codigo: '', historico: [{ t: agora, e: 'cadastro' }] };
  const msg = P.c ? carimba(c, P.c) : '';
  guarda(c);
  sets.push({ chave: `fidt:${prog.id}:${P.fone}`, valor: c.cid, ttl: ANO });
  somas.push(`fidst:${prog.id}:novos:${dia}`);
  return sai(200, { ok: true, cid: c.cid, token: tokenDe(c.cid), carimbou: !!P.c && !msg, aviso: msg, estado: estado(c) });
}

// daqui para baixo o celular já tem cartão: o token prova que é dele
if (!cli || !P.cid || P.token !== tokenDe(P.cid)) return erro('Cartão não encontrado neste celular. Crie ou recupere o cartão.', 401, { sair: true });
if (P.acao === 'estado') return sai(200, { ok: true, estado: estado(cli) });

if (P.acao === 'carimbar') {
  const msg = carimba(cli, P.c);
  if (msg) return erro(msg, 400, { estado: estado(cli) });
  guarda(cli);
  return sai(200, { ok: true, carimbou: true, estado: estado(cli) });
}

if (P.acao === 'resgatar') {
  if (cli.premios < 1) return erro('Você ainda não tem prêmio para resgatar.', 400, { estado: estado(cli) });
  if (!pend) {
    pend = { cid: cli.cid, nome: cli.nome, codigo: String(crypto.randomInt(1000, 10000)), criado: agora };
    sets.push({ chave: `fidr:${prog.id}:${cli.cid}`, valor: JSON.stringify(pend), ttl: 1800 });
    somas.push(`fidst:${prog.id}:pedidos_resgate:${dia}`);
  }
  return sai(200, { ok: true, estado: estado(cli) });
}

if (P.acao === 'inscrever') {
  const s = P.sub || {};
  let ok = typeof s.endpoint === 'string' && /^https:\/\//.test(s.endpoint) && s.endpoint.length < 1000 && s.keys && s.keys.p256dh && s.keys.auth;
  // a chave do celular tem de ser um ponto válido da curva P-256: uma chave quebrada derrubaria o envio para todos os clientes
  try {
    const b = t => Buffer.from(String(t).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
