  somas.push(`fidst:${prog.id}:avisos_ligados`);
  return sai(200, { ok: true, estado: estado(cli) });
}
return erro('Pedido inválido.');

// sempre ao menos 1 soma, para o fluxo seguir até a resposta
const d = $('🎟️ Decide o cartão').first().json;
return (d.somas.length ? d.somas : [`fidst:${d.id}:uso:${d.dia}`]).map(chave => ({ json: { chave } }));

// Tela do balcão (tablet ou celular do dono): QR que muda a cada 30 s para o cliente carimbar + prêmios esperando o atendente confirmar.
const q = $('🔔 Abrir balcão (GET)').first().json.query || {};
let p = null;
try { p = JSON.parse($('📖 Lê o programa (balcão)').first().json.programa || 'null'); } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
if (!p || String(q.chave || '') !== p.chave) {
  return [{ json: { codigo: 403, html: `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Balcão</title><meta name="robots" content="noindex"></head>
<body style="font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;background:#f6f6f4;color:#222;text-align:center;padding:24px">
<div><div style="font-size:56px">🔒</div><h1 style="font-size:22px">Link do balcão inválido</h1><p style="color:#666">Abra o balcão pelo link do painel do dono.</p></div></body></html>` } }];
}
const lum = c => { const v = [1, 3, 5].map(i => parseInt(c.slice(i, i + 2), 16) / 255).map(x => x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4)); return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2]; };
const corTexto = lum(p.cor) > 0.45 ? '#111111' : '#ffffff';

// roda na tela do balcão
function balcao(B) {
  var el = function (s) { return document.querySelector(s); };
  var API = '/webhook/fidelidade-dono', atual = '', troca = 0, vistos = {};
  function api(d) {
    return fetch(API, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(Object.assign({ id: B.id, chave: B.chave }, d)) })
      .then(function (r) { return r.json(); }).catch(function () { return { ok: false, erro: 'Sem conexão com a internet.' }; });
  }
  function toast(t) { var x = el('#toast'); x.textContent = t; x.classList.add('on'); clearTimeout(x._t); x._t = setTimeout(function () { x.classList.remove('on'); }, 4000); }
  function buscaQR() {
    api({ acao: 'codigo' }).then(function (r) {
      if (!r.ok) { el('#estado').textContent = '⚠️ ' + (r.erro || 'Não deu para gerar o QR.') + ' Tentando de novo…'; setTimeout(buscaQR, 5000); return; }
      el('#estado').textContent = '';
      if (r.url !== atual) {
        atual = r.url;
        var qr = qrcode(0, 'M'); qr.addData(r.url); qr.make();
        el('#qr').innerHTML = qr.createSvgTag({ cellSize: 6, margin: 2, scalable: true });
      }
      troca = Date.now() + r.troca_em;
      setTimeout(buscaQR, Math.max(1000, r.troca_em + 400));
    });
  }
  (function relogio() {
    var falta = Math.max(0, troca - Date.now());
    el('#tempo i').style.width = (falta / 30000 * 100) + '%';
    el('#tempo-txt').textContent = !troca ? 'Gerando o QR…' : falta > 0 ? 'Este QR muda em ' + Math.ceil(falta / 1000) + ' s' : 'Trocando o QR…';
    requestAnimationFrame(relogio);
  })();
  function buscaPendentes() {
    api({ acao: 'pendentes' }).then(function (r) {
      if (r.ok) {
        var lista = r.pendentes || [];
        el('#pend-vazio').hidden = lista.length > 0;
        el('#pendentes').innerHTML = lista.map(function (x) {
