          return '<li class="' + (novo ? 'novo' : '') + '"><div><b>' + String(x.nome).replace(/[<>&]/g, '') + '</b><small>código no celular: <strong>' + x.codigo + '</strong></small></div>'
            + '<button class="bt" data-cid="' + x.cid + '" data-codigo="' + x.codigo + '" data-nome="' + String(x.nome).replace(/["<>&]/g, '') + '">✅ Entregar</button></li>';
        }).join('');
        if (lista.some(function (x) { return vistos[x.cid] === 1; })) { lista.forEach(function (x) { vistos[x.cid] = 2; }); if (navigator.vibrate) navigator.vibrate(200); }
      }
      setTimeout(buscaPendentes, 4000);
    });
  }
  el('#pendentes').addEventListener('click', function (e) {
    var b = e.target.closest('button[data-cid]'); if (!b) return;
    if (!confirm('Entregar o prêmio para ' + b.dataset.nome + '?\nConfira se o código no celular dele é ' + b.dataset.codigo + '.')) return;
    b.disabled = true; b.textContent = '⏳';
    api({ acao: 'entregar', cid: b.dataset.cid, codigo: b.dataset.codigo }).then(function (r) {
      toast(r.ok ? '🎉 Prêmio entregue para ' + r.nome + '!' : '⚠️ ' + r.erro);
      b.closest('li').remove();
      el('#pend-vazio').hidden = !!el('#pendentes li');
    });
  });
  // tela sempre acesa e tela cheia (tablet no balcão)
  var trava = null;
  function acende() { if ('wakeLock' in navigator) navigator.wakeLock.request('screen').then(function (t) { trava = t; }).catch(function () {}); }
  document.addEventListener('visibilitychange', function () { if (!document.hidden) acende(); });
  acende();
  el('#bt-cheia').addEventListener('click', function () { var d = document.documentElement; if (d.requestFullscreen) d.requestFullscreen().catch(function () {}); });
  buscaQR(); buscaPendentes();
}

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
