return [{ json: { codigo: 200, html } }];

// Lê o pedido do balcão ou do painel (só vale com a chave do painel, conferida no próximo passo).
let b = $('🔔 Pedido do dono (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const ACOES = ['codigo', 'pendentes', 'entregar', 'avisar', 'sugerir'];
const GRUPOS = ['todos', 'quase', 'premio', 'sumidos', 'aniversariantes'];
const id = /^[a-z0-9-]{4,60}$/.test(String(b.id || '')) ? String(b.id) : '';
const cid = /^[a-f0-9]{12}$/.test(String(b.cid || '')) ? String(b.cid) : '';
return [{ json: { acao: ACOES.includes(b.acao) ? b.acao : 'invalida', id, cid, chave: String(b.chave || '').slice(0, 40),
  codigo: String(b.codigo || '').replace(/\D/g, '').slice(0, 6), grupo: GRUPOS.includes(b.grupo) ? b.grupo : 'todos',
  titulo: limpa(b.titulo, 50), texto: limpa(b.texto, 170), ideia: limpa(b.ideia, 200),
  k_programa: 'fid:' + (id || '-'), k_cliente: 'fidc:' + (id || '-') + ':' + (cid || '-'),
  base: String($('🔔 Pedido do dono (POST)').first().json.webhookUrl || '').split('/webhook/')[0] + '/webhook' } }];

// Ações do dono: QR do balcão (muda a cada 30 s), resgates esperando, entregar prêmio, mandar aviso e pedir sugestão à IA.
const crypto = require('crypto');
const P = $('🧩 Lê o pedido do dono').first().json;
let prog = null, cli = null;
try { prog = JSON.parse($('📖 Lê o programa (dono)').first().json.programa || 'null'); } catch (e) {}
try { cli = JSON.parse($('📖 Lê o cliente (dono)').first().json.cliente || 'null'); } catch (e) {}
const agora = Date.now();
const dia = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });
const sets = [], somas = [];
const sai = (rota, codigo, corpo, extra = {}) => [{ json: { rota, codigo, resposta: JSON.stringify(corpo), sets, somas, id: P.id, dia, ...extra } }];
const erro = (msg, codigo = 400) => sai('responder', codigo, { ok: false, erro: msg });

if (!prog || !P.chave || P.chave !== prog.chave) return erro('Chave do painel errada ou programa não encontrado.', 403);
const hmac = t => crypto.createHmac('sha256', prog.segredo).update(t).digest('hex');

if (P.acao === 'codigo') {
  const janela = Math.floor(agora / 30000);
  const c = janela + '.' + hmac('qr:' + janela).slice(0, 10);
  return sai('responder', 200, { ok: true, c, url: `${P.base}/fidelidade/${prog.id}/cartao?c=${c}`, troca_em: 30000 - agora % 30000 });
}

const pendentes = Object.entries($('🗂️ Lê os resgates pendentes').first().json || {}).filter(([k]) => k.startsWith(`fidr:${prog.id}:`)).map(([, v]) => {
  try { return JSON.parse(v); } catch (e) { return null; }
}).filter(x => x && x.cid && x.codigo).sort((a, b) => a.criado - b.criado);

if (P.acao === 'pendentes') return sai('responder', 200, { ok: true, pendentes: pendentes.map(x => ({ cid: x.cid, nome: x.nome, codigo: x.codigo, criado: x.criado })) });

if (P.acao === 'entregar') {
  const pend = pendentes.find(x => x.cid === P.cid);
  if (!pend || !cli) return erro('Esse resgate não está mais esperando (passou de 30 minutos ou já foi entregue).', 404);
  if (pend.codigo !== P.codigo) return erro('O código não confere com o do celular do cliente.');
  if (cli.premios < 1) return erro('Esse cliente não tem prêmio para retirar.');
  cli.premios -= 1; cli.resgatados += 1;
  cli.historico.unshift({ t: agora, e: 'resgate' }); cli.historico = cli.historico.slice(0, 40);
  sets.push({ chave: `fidc:${prog.id}:${cli.cid}`, valor: JSON.stringify(cli), ttl: 31536000 });
  sets.push({ chave: `fidr:${prog.id}:${cli.cid}`, valor: '', ttl: 1 });  // apaga o pedido de resgate (vence em 1 s)
  somas.push(`fidst:${prog.id}:resgates:${dia}`);
  return sai('gravar', 200, { ok: true, nome: cli.nome, premio: prog.premio });
}

if (P.acao === 'avisar') {
  if (!P.titulo || !P.texto) return erro('Escreva o título e a mensagem do aviso.');
  return sai('avisar', 200, { ok: true }, { prog });
}
if (P.acao === 'sugerir') {
  const GRUPO = { todos: 'todos os clientes com avisos ligados', quase: 'clientes a 1 ou 2 carimbos do prêmio', premio: 'clientes que já completaram o cartão e ainda não retiraram o prêmio',
    sumidos: `clientes que não aparecem há ${prog.dias_saudade || 30} dias ou mais`, aniversariantes: 'clientes que fazem aniversário este mês' };
  const texto_ia = `NEGÓCIO: ${prog.nome} (${prog.tipo || 'pequeno negócio'})\nPROGRAMA: ${prog.meta} carimbos = ${prog.premio}${prog.regra ? ' · carimbo ' + prog.regra : ''}`
    + (prog.aniversario ? `\nPRESENTE DE ANIVERSÁRIO: ${prog.aniversario}` : '') + `\nGRUPO QUE VAI RECEBER: ${GRUPO[P.grupo]}\nIDEIA DO DONO: ${P.ideia || '(nenhuma: sugira algo que combine com o grupo)'}`;
  return sai('sugerir', 200, { ok: true }, { texto_ia });
}
return erro('Pedido inválido.');

// Web Push: a mensagem vai criptografada só para aquele celular (RFC 8291) e assinada com a chave do programa (VAPID, RFC 8292).
const b64u = buf => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb = s => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/'), 'base64');
function criptografa(sub, texto) {
  const cr = require('crypto');
  const uaPublica = unb(sub.keys.p256dh), segredo = unb(sub.keys.auth);
  const ecdh = cr.createECDH('prime256v1'); ecdh.generateKeys();
  const asPublica = ecdh.getPublicKey();
  const compartilhado = ecdh.computeSecret(uaPublica);
  const sal = cr.randomBytes(16);
  const info = Buffer.concat([Buffer.from('WebPush: info\0'), uaPublica, asPublica]);
  const ikm = Buffer.from(cr.hkdfSync('sha256', compartilhado, segredo, info, 32));
  const cek = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: aes128gcm\0'), 16));
  const nonce = Buffer.from(cr.hkdfSync('sha256', ikm, sal, Buffer.from('Content-Encoding: nonce\0'), 12));
  const c = cr.createCipheriv('aes-128-gcm', cek, nonce);
  const cifrado = Buffer.concat([c.update(Buffer.concat([Buffer.from(texto, 'utf8'), Buffer.from([2])])), c.final(), c.getAuthTag()]);
  const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
  return Buffer.concat([sal, rs, Buffer.from([asPublica.length]), asPublica, cifrado]);
}
function vapid(prog, endpoint) {
  const cr = require('crypto');
  const cab = b64u(JSON.stringify({ typ: 'JWT', alg: 'ES256' }));
  // "aud" = endereço do serviço de avisos (Google, Apple ou Mozilla); o Code node não tem URL(), então recorto o texto
  const corpo = b64u(JSON.stringify({ aud: (String(endpoint).match(/^https:\/\/[^/]+/) || [''])[0], exp: Math.floor(Date.now() / 1000) + 12 * 3600,
    sub: 'https://webhookn8n6.inovareinteligenciaartificial.com' }));
  const assinatura = cr.sign('sha256', Buffer.from(cab + '.' + corpo), { key: cr.createPrivateKey({ key: prog.vapid.privada, format: 'jwk' }), dsaEncoding: 'ieee-p1363' });
  return `vapid t=${cab}.${corpo}.${b64u(assinatura)}, k=${prog.vapid.publica}`;
}
// {nome} = primeiro nome do cliente · {faltam} = carimbos que faltam para o prêmio
const pers = (t, c, prog) => String(t || '').replace(/\{nome\}/g, String(c.nome || '').split(' ')[0]).replace(/\{faltam\}/g, Math.max(1, prog.meta - c.carimbos));

// Quem está em cada grupo. O painel conta com a mesma regra usada para mandar os avisos.
const DIA_MS = 86400000;
function noGrupo(c, grupo, prog, agora) {
  const parado = (agora - (c.ultimo_carimbo || c.criado || 0)) / DIA_MS;
  const mes = new Date(agora).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit' }).slice(3);
  if (grupo === 'todos') return true;
  if (grupo === 'premio') return c.premios > 0;
  if (grupo === 'quase') return c.premios === 0 && c.carimbos > 0 && prog.meta - c.carimbos <= 2;
  if (grupo === 'sumidos') return parado >= (prog.dias_saudade || 30);
  if (grupo === 'aniversariantes') return !!c.aniversario && c.aniversario.slice(3) === mes;
  return false;
}

// Prepara o aviso do painel para cada celular do grupo escolhido ({nome} e {faltam} viram o nome e os carimbos de cada cliente).
