Object.entries($('🗂️ Lê os clientes (dono)').first().json || {}).forEach(([k, v]) => {
  if (k.startsWith(`fidc:${prog.id}:`)) { try { const c = JSON.parse(v); clientes[c.cid] = c; } catch (e) {} }
});
const alvos = Object.entries($('🗂️ Lê os inscritos (dono)').first().json || {}).filter(([k]) => k.startsWith(`fidpush:${prog.id}:`)).map(([chave, v]) => {
  let sub = null;
  try { sub = JSON.parse(v); } catch (e) {}
  const c = clientes[chave.split(':')[2]];
  return sub && sub.endpoint && c && noGrupo(c, P.grupo, prog, agora) ? { chave, sub, c } : null;
}).filter(Boolean);
// inscrição com chave quebrada não derruba o envio dos outros: é pulada e sai da lista junto com quem desinstalou
const saida = [], invalidos = [];
for (const { chave, sub, c } of alvos) {
