}
if (!saida.length) return [{ json: { vazio: true, invalidos } }];
saida[0].json.invalidos = invalidos;
return saida;

// Conta quantos celulares receberam. 201 = entregue · 404/410 = a pessoa desinstalou ou desligou os avisos (sai da lista).
