  ['🔔', inscritos.size, 'com avisos ligados', clientes.length ? Math.round(inscritos.size / clientes.length * 100) + '% dos clientes' : '—'],
];

// cores do gráfico: a cor do negócio com contraste mínimo de 3:1 contra o fundo do cartão (claro e escuro)
const hex = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));
const paraHex = a => '#' + a.map(v => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
