function painel(D) {
  var el = function (s) { return document.querySelector(s); };
  var API = '/webhook/fidelidade-dono';
  var NOMES_G = D.grupos, ordem = { campo: 'ultima', dir: -1 }, filtroG = '', busca = '';
  function api(d) {
