      el('#titulo').value = r.titulo; el('#texto').value = r.texto;
      msg.textContent = '✨ Sugestão pronta' + (r.revisado ? ' e conferida pela revisora' : '') + ': ajuste se quiser e toque em Enviar.' + (r.problemas && r.problemas.length ? ' A revisora mudou: ' + r.problemas.join(' · ') : '');
    });
